#!/usr/bin/env python3
"""Generate the test-only expansion locale from canonical ARB signatures.

Run after changing catalogs. --check validates the tracked fixture without edits.
No pseudo locale is registered by the production app or native bundles.
"""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'lib/l10n/app_en.arb'
TARGET = ROOT / 'test/support/pseudo_localizations.dart'


def generate():
    catalog = json.loads(SOURCE.read_text())
    lines = [
        '// Generated by tool/generate_pseudo_localizations.py; do not edit.',
        "import 'package:flutter/foundation.dart';",
        "import 'package:flutter/widgets.dart';",
        "import 'package:litch_mobile/l10n/generated/app_localizations.dart';",
        "import 'package:litch_mobile/l10n/generated/app_localizations_en.dart';",
        '',
        '// Retain formatted values (P1/P2, notation, versions) verbatim. Padding',
        '// expands each message by ~40% and brackets reveal untranslated chrome.',
        "String _expand(String value) => '[[$value${'.' * (value.length * .4).ceil()}]]';",
        '',
        'class PseudoLocalizations extends AppLocalizationsEn {',
        "  PseudoLocalizations() : super('en_XA');",
    ]
    for key in catalog:
        if key.startswith('@'):
            continue
        placeholders = catalog.get('@' + key, {}).get('placeholders', {})
        signature = ', '.join(f"{meta.get('type', 'Object')} {name}" for name, meta in placeholders.items())
        arguments = ', '.join(placeholders)
        expression = f'{key}({arguments})' if placeholders else key
        declaration = f'{key}({signature})' if placeholders else f'get {key}'
        lines += ['  @override', f'  String {declaration} => _expand(super.{expression});']
    lines += [
        '}', '',
        'class PseudoLocalizationsDelegate extends LocalizationsDelegate<AppLocalizations> {',
        '  const PseudoLocalizationsDelegate();',
        '  @override',
        "  bool isSupported(Locale locale) => locale == const Locale('en', 'XA');",
        '  @override',
        '  Future<AppLocalizations> load(Locale locale) => SynchronousFuture(PseudoLocalizations());',
        '  @override',
        '  bool shouldReload(PseudoLocalizationsDelegate old) => false;',
        '}', '',
    ]
    return '\n'.join(lines)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = generate()
    if args.check:
        if not TARGET.exists() or TARGET.read_text() != expected:
            parser.exit(1, 'Pseudo fixture is stale. Run python3 tool/generate_pseudo_localizations.py\n')
    else:
        TARGET.parent.mkdir(parents=True, exist_ok=True)
        TARGET.write_text(expected)
